const body = $input.first().json.body || {};

const image_base64 = body.image_base64 || null;
const site_id = body.site_id || 'unknown';

if (!image_base64 || image_base64.trim().length === 0) {
  throw new Error('Missing required field: image_base64 not found in request body.');
}

return [{
  json: {
    image_base64: image_base64.trim(),
    site_id: site_id
  }
}];

const image_base64 = $input.item.json.image_base64;
const site_id = $input.item.json.site_id;

const auditPrompt = "You are a strict Fire Safety Compliance Auditor operating under NBC 2016 and CFO Mumbai norms. Inspect this image of fire safety equipment and evaluate compliance. Check for: 1) Pressure gauges \u2014 needle must be in green zone; 2) Safety pin \u2014 must be intact and sealed with tamper tag; 3) ISI mark \u2014 must be visible on cylinder body; 4) Hose reel glass \u2014 must be unbroken; 5) Expiry date \u2014 must not be expired; 6) Physical damage \u2014 no dents, rust, or corrosion; 7) Mounting \u2014 must be properly mounted at correct height; 8) Signage \u2014 inspection tag must be present and current. Return ONLY valid JSON with no markdown, no explanation, no code blocks. Exact schema: {\"equipment_type\": \"string\", \"status\": \"COMPLIANT or NON-COMPLIANT\", \"confidence\": \"HIGH or MEDIUM or LOW\", \"observations\": \"string describing what you see\", \"violations\": [\"list of violation strings, empty array if compliant\"]}";

const payload = {
  model: 'anthropic/claude-3.5-sonnet',
  max_tokens: 1024,
  messages: [
    {
      role: 'user',
      content: [
        {
          type: 'image',
          source: {
            type: 'base64',
            media_type: 'image/jpeg',
            data: image_base64
          }
        },
        {
          type: 'text',
          text: auditPrompt
        }
      ]
    }
  ]
};

return [{
  json: {
    payload: payload,
    site_id: site_id
  }
}];

const raw = $input.first().json.choices?.[0]?.message?.content || '';

// Strip markdown fences if Claude accidentally adds them
let cleaned = raw
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/g, '')
  .trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {
    equipment_type: 'Unknown',
    status: 'ERROR',
    confidence: 'LOW',
    observations: 'Failed to parse AI response: ' + e.message,
    violations: ['AI_PARSE_ERROR']
  };
}

const site_id = $('BUILD_Vision_Payload').first().json.site_id || 'unknown';

return [{
  json: {
    ...parsed,
    site_id: site_id,
    audit_timestamp: new Date().toISOString()
  }
}];

const status = $input.item.json.status;
const site_id = $input.item.json.site_id;
const violations = $input.item.json.violations || [];
const equipment = $input.item.json.equipment_type || 'Unknown Equipment';
const confidence = $input.item.json.confidence || 'N/A';
const timestamp = $input.item.json.audit_timestamp || new Date().toISOString();

const violationList = violations.length > 0
  ? violations.map((v, i) => `  ${i + 1}. ${v}`).join('\n')
  : '  None recorded';

const alert = [
  '🚨 AUDIT FAILED — IMMEDIATE ACTION REQUIRED',
  '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
  `Site ID     : ${site_id}`,
  `Equipment   : ${equipment}`,
  `Status      : ${status}`,
  `Confidence  : ${confidence}`,
  `Timestamp   : ${timestamp}`,
  '',
  'VIOLATIONS DETECTED:',
  violationList,
  '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
  'Action: Notify site supervisor and schedule immediate maintenance.'
].join('\n');

return [{
  json: {
    alert: alert,
    site_id: site_id,
    status: status,
    equipment_type: equipment,
    violations: violations,
    audit_timestamp: timestamp
  }
}];
